window.WORLD_MAP_SPEC = { width: 1000, height: 500, latMax: 78, latMin: -58 };

window.projectLonLat = function (lon, lat) {
  const x = ((lon + 180) / 360) * 1000;
  const clamped = Math.max(-58, Math.min(78, lat));
  const y = ((78 - clamped) / (78 - -58)) * 500;
  return [x, y];
};

